<?php
/** Phase 7F pure logic tests (no database, no network). */
if (PHP_SAPI !== 'cli') { http_response_code(404); exit; }
ob_start(); $root = dirname(__DIR__); require_once $root . '/helpers.php'; require_once $root . '/ad_core.php'; ob_end_clean();
$pass = 0; $fail = 0; function ok(bool $c, string $m): void { global $pass, $fail; if ($c) $pass++; else { $fail++; fwrite(STDERR, "  FAIL: $m\n"); } }
$st = ad_statuses(); ok(array_keys($st) === ['draft', 'enquiry_received', 'proposal_sent', 'awaiting_payment', 'scheduled', 'active', 'paused', 'completed', 'cancelled', 'expired'], 'the ten required campaign statuses in order'); $tr = ad_transitions();
foreach ($tr as $f => $ts) foreach ($ts as $t) if (!isset($st[$t])) ok(false, "unknown target $t"); ok($tr['completed'] === [] && $tr['cancelled'] === [] && $tr['expired'] === [], 'completed, cancelled and expired are final');
