ok(AD_HOLDS === ['awaiting_payment', 'scheduled', 'active', 'paused'], 'inventory is held from awaiting payment until the campaign ends');
ok(ad_overlap('2026-01-01', '2026-01-31', '2026-01-31', '2026-02-10') && !ad_overlap('2026-01-01', '2026-01-30', '2026-01-31', '2026-02-10') && ad_overlap('2026-01-05', '2026-01-10', '2026-01-01', '2026-01-31') && !ad_overlap(null, '2026-01-02', '2026-01-01', '2026-01-02'), 'date overlap is inclusive and tolerant of missing dates');
ok(ad_status_from_campaign('inquiry') === 'enquiry_received' && ad_status_from_campaign('live') === 'active' && ad_status_from_campaign('rejected') === 'cancelled' && ad_status_from_campaign('nonsense') === 'draft', 'CRM campaign status maps to the advertising lifecycle');
ok(ad_minor(4900) === '49.00' && ad_minor(5) === '0.05' && ad_minor(100000000) === '1000000.00', 'minor units to a decimal string');
[$o, $c] = ad_package_clean(['name' => 'Featured Tool', 'kind' => 'featured_tool', 'price' => '49', 'currency' => 'USD', 'duration_days' => '30', 'billing' => 'one_off', 'slots' => '3', 'scope' => 'global', 'public_slot' => 'level1', 'available' => '1']); ok($o && $c['price_minor'] === 4900 && $c['duration_days'] === 30 && $c['slots'] === 3 && $c['available'] === 1 && $c['exclusive'] === 0, 'valid package cleaned');
